/**
 * 负责定义领域组件名称与存储对象之间的类型关系。输入为既有十一种槽 ID 和组件接口；
 * 输出使 World 按具名槽返回原可写组件引用，调用方不再以任意泛型覆盖槽结构；不复制值或存储。工厂与生命周期所有者
 * 仍负责各自校验，此关系不授予资源权限或序列化运行句柄。
 */
import type { COMPONENT, ComponentName } from "./components/names";
import type { IdentityComponent } from "./entities/player";
import type { RoleComponent } from "./components/role";
import type { CampComponent } from "./components/camp";
import type { AliveComponent } from "./components/alive";
import type { VotingRightComponent } from "./components/voting_right";
import type { StatusMarksComponent } from "./components/status_marks";
import type { BadgeComponent } from "./components/badge";
import type { VictoryComponent } from "./components/victory";
import type { LoversComponent } from "./components/lovers";
import type { WallNoteComponent } from "./components/wall_note";
import type { DebatePenaltyComponent } from "./components/debate_penalty";

/** 十一具名槽分别关联其原组件类型；该映射不创建实例，也不把两个槽的字段合成一个对象。 */
export interface ComponentMap {
  [COMPONENT.Identity]: IdentityComponent;
  // 角色身份／私有容器与实际阵营是两个独立槽；当前阵营不再镜像到 Role。
  [COMPONENT.Role]: RoleComponent;
  [COMPONENT.Camp]: CampComponent;
  [COMPONENT.Alive]: AliveComponent;
  [COMPONENT.VotingRight]: VotingRightComponent;
  [COMPONENT.StatusMarks]: StatusMarksComponent;
  [COMPONENT.Badge]: BadgeComponent;
  [COMPONENT.Victory]: VictoryComponent;
  [COMPONENT.Lovers]: LoversComponent;
  [COMPONENT.WallNote]: WallNoteComponent;
  [COMPONENT.DebatePenalty]: DebatePenaltyComponent;
}

/** 汇总既有槽的公开字段名，供写入类型排除其它槽字段；自定义扩展名仍可由具体输入保留。 */
type ComponentFields = {
  [K in ComponentName]: keyof ComponentMap[K];
}[ComponentName];

/**
 * 保留自定义扩展字段，同时在类型上排除其它槽的公开字段。Role 与 Camp 分属独立槽，
 * role／privateState 不能装入 Camp 槽，camp 不能装入 Role 槽；展示方法已退出组件结构。
 * optional never 与最终 never 分支仅约束编译期槽关系，不执行运行 shape 检查、冻结或授权，
 * 也不把扩展对象限制为精确字段集合。
 */
export type ComponentWrite<K extends ComponentName> = K extends ComponentName
  ? ComponentMap[K] & {
      [P in Exclude<ComponentFields, keyof ComponentMap[K]>]?: never;
    }
  : never;

/**
 * 负责按身份、板子、动作、事件、结果与死亡概念聚合既有领域出口；输出保持原值／类型绑定。
 * 具体契约仍由各概念及 game-contract 拥有，这里不定义第二套枚举、状态或规则。
 * 原重导出顺序和下游模块加载关系保持；出口本身不创建角色、授予请求权限或封盘。
 */
export * from "./identity";
export * from "./board";
export * from "./actions";
export * from "./events";
export * from "./results";
export * from "./deaths";

/**
 * 负责公开杠精辩论禁票处罚的数据结构；输入为处罚日次、来源编号和捕获的生命版本。
 * 实际 record 引用与原 NightLifeScope 另由辩论 authority 保存并查询；这些数字不能重建其许可。
 * 接口字段保持可写，不冻结、安装、撤销或执行处罚；缺省日次和生命复验沿原运行查询。
 */
export interface DebatePenaltyComponent {
  /** 处罚所属日次；运行查询的 day 缺省接受面由 authority 决定，不在字段定义中统一到期。 */
  day: number;
  /** 原处罚来源的实体编号；不是请求 token，也不独立证明该来源当前存活或有权提交。 */
  sourceId: number;
  /** 记录捕获时的生命版本；真实当前性还依赖 authority 保存的原生命对象与组件引用。 */
  lifeVersion: number;
}

/**
 * 负责保留胜负系统的既有两参数委托入口；输入原 World 与条件，输出注入评估器的原判定或 null。
 * 规则实现及允许检查点由原评估器拥有，阶段执行和最终封盘仍归管理器；这里不标死或改写结果。
 * 实例只保存原评估器引用，方法读取／调用失败原样传播，不增加缓存、回退规则或配置校验。
 */
import { WinDecision, WinCondition } from "../model";
import { World } from "../world";
import { WinConditionEvaluator } from "../registries/condition_registry";

/**
 * 兼容层：
 * 历史上由该系统直接硬编码胜负规则，现改为委托机制注册中心。
 */
export class WinConditionSystem {
  private readonly registry: WinConditionEvaluator;

  constructor(registry: WinConditionEvaluator) {
    this.registry = registry;
  }

  evaluate(world: World, condition: WinCondition): WinDecision | null {
    return this.registry.evaluate(world, condition);
  }
}

/**
 * core 门面导出：领域模型与基础组件。
 */
export * from "./domain";

import { sanitizeSpeechText } from "../../utils/speech_text";
import { EntityId, ToolCall, ToolValidationResult } from "../../core/domain/model";
import { World } from "../../core/domain/world";
import { ActionValidator, type ValidationContext } from "./action_validator";

/**
 * ToolGateway 负责两件事：
 * 在执行前做输入清洗与领域规则校验。传输入参的JSON Schema由ActionReception持有。
 */
export class ToolGateway {
  private readonly validator: ActionValidator;

  constructor(validator: ActionValidator = new ActionValidator()) {
    this.validator = validator;
  }

  validateAndSanitize<T extends ToolCall>(
    world: World,
    actorId: EntityId,
    toolCall: T,
    context: ValidationContext,
  ): ToolValidationResult<T> {
    const sanitizedCall = this.sanitize(toolCall);
    return this.validator.validate(world, actorId, sanitizedCall, context);
  }

  private sanitize<T extends ToolCall>(call: T): T {
    if (call.name === "speak") {
      const raw = call.args.text;
      // 防止模型伪造系统身份前缀，避免污染公共上下文。
      const text = sanitizeSpeechText(raw);
      return {
        ...call,
        args: {
          ...call.args,
          text,
        },
      } as T;
    }
    if (call.name === "speak_to_wolves") {
      const raw = call.args.text;
      const text = sanitizeSpeechText(raw);
      return {
        ...call,
        args: {
          ...call.args,
          text,
          end_chat: Boolean(call.args.end_chat),
        },
      } as T;
    }
    return call;
  }
}
